old = open('app/src/i18n.js').read()
hero = {}
for lang in ('en', 'pt'):
    blk = old[old.index('  ' + lang + ': {'):]
    hero[lang] = {k: json.loads(re.search(r"[\"']" + re.escape(k) + r"[\"']: (\"(?:[^\"\\]|\\.)*\")", blk).group(1)) for k in ('title', 'hero.eyebrow', 'hero.h1', 'hero.lede')}
out = ['/* ══ Diccionarios de la app (español = idioma de origen). Generado por tr.py: edita allí y vuelve a generar. ══ */', 'const I18N = {']
for i, lang in enumerate(('en', 'pt')):
    d = dict(hero[lang]); d.update({k: v[i] for k, v in T.items()})
    out.append('  ' + lang + ': ' + json.dumps(d, ensure_ascii=False, indent=0).replace('\n', ' ') + (',' if i == 0 else ''))
out.append('};')
open('app/src/i18n.js', 'w').write('\n'.join(out) + '\n')
print(len(T), 'entradas')
